  1253                               struct ndpi_flow_struct *flow, uint32_t quic_version) {
  1254    struct ndpi_packet_struct *packet = &ndpi_struct->packet;
  1255    union ja3_info ja3;
  1256    u_int8_t invalid_ja3 = 0;
  1257    u_int16_t tls_version, ja3_str_len;
