  1266
  1267  #ifdef DEBUG_TLS
  1268    printf("TLS %s() called\n", __FUNCTION__);
  1269  #endif
  1270
  1271
  1272    handshake_type = packet->payload[0];
  1273    total_len = (packet->payload[1] << 16) +  (packet->payload[2] << 8) + packet->payload[3];
  1274
  1275    if((total_len > packet->payload_packet_len) || (packet->payload[1] != 0x0))
  1276      return(0); /* Not found */
  1277
  1278    total_len = packet->payload_packet_len;
  1279
