  1281    if(total_len > 4) {
  1282      u_int16_t base_offset    = (!is_dtls) ? 38 : 46;
  1283      u_int16_t version_offset = (!is_dtls) ? 4 : 12;
  1284      u_int16_t offset = (!is_dtls) ? 38 : 46;
  1285      u_int32_t tot_extension_len;
  1286      u_int8_t  session_id_len =  0;
  1287
  1288      if((base_offset >= total_len) ||
  1289         (version_offset + 1) >= total_len)
  1290        return 0; /* Not found */
  1291
  1292      session_id_len = packet->payload[base_offset];
  1293
  1294  #ifdef DEBUG_TLS
  1295      printf("TLS [len: %u][handshake_type: %02X]\n", packet->payload_packet_len, handshake_type);
  1296  #endif
  1297
  1298      tls_version = ntohs(*((u_int16_t*)&packet->payload[version_offset]));
  1299
  1300      if(handshake_type == 0x02 /* Server Hello */) {
  1301        int rc;
  1302
  1303        ja3.server.num_cipher = 0;
  1304        ja3.server.num_tls_extension = 0;
  1305        ja3.server.num_elliptic_curve_point_format = 0;
  1306        ja3.server.alpn[0] = '\0';
  1307
  1308        ja3.server.tls_handshake_version = tls_version;
  1309
  1310  #ifdef DEBUG_TLS
  1311        printf("TLS Server Hello [version: 0x%04X]\n", tls_version);
  1312  #endif
  1313
  1314        /*
  1315          The server hello decides about the TLS version of this flow
  1315          The server hello decides about the TLS version of this flow
  1316          https://networkengineering.stackexchange.com/questions/55752/why-does-wireshark-show-version-tls-1-2-here-instead-of-tls-1-3
  1317        */
  1318        if(packet->udp)
  1319          offset += session_id_len + 1;
  1320        else {
  1321          if(tls_version < 0x7F15 /* TLS 1.3 lacks of session id */)
  1322            offset += session_id_len+1;
  1323        }
  1324
  1325        if((offset+3) > packet->payload_packet_len)
  1326          return(0); /* Not found */
  1327
  1328        ja3.server.num_cipher = 1, ja3.server.cipher[0] = ntohs(*((u_int16_t*)&packet->payload[offset]));
  1329        if((flow->protos.tls_quic.server_unsafe_cipher = ndpi_is_safe_ssl_cipher(ja3.server.cipher[0])) == 1)
  1330          ndpi_set_risk(ndpi_struct, flow, NDPI_TLS_WEAK_CIPHER);
  1331
  1332        flow->protos.tls_quic.server_cipher = ja3.server.cipher[0];
  1333
  1334  #ifdef DEBUG_TLS
  1335        printf("TLS [server][session_id_len: %u][cipher: %04X]\n", session_id_len, ja3.server.cipher[0]);
  1336  #endif
  1337
  1338        offset += 2 + 1;
  1339
  1340        if((offset + 1) < packet->payload_packet_len) /* +1 because we are goint to read 2 bytes */
  1341          tot_extension_len = ntohs(*((u_int16_t*)&packet->payload[offset]));
  1342        else
  1343          tot_extension_len = 0;
  1344
  1345  #ifdef DEBUG_TLS
  1346        printf("TLS [server][tot_extension_len: %u]\n", tot_extension_len);
  1347  #endif
  1348        offset += 2;
  1349
  1350        for(i=0; i<tot_extension_len; ) {
  1351          u_int16_t extension_id;
  1352          u_int32_t extension_len;
  1353
  1354          if((offset+4) > packet->payload_packet_len) break;
  1355
  1356          extension_id  = ntohs(*((u_int16_t*)&packet->payload[offset]));
  1357          extension_len = ntohs(*((u_int16_t*)&packet->payload[offset+2]));
  1358          if(offset+4+extension_len > packet->payload_packet_len) {
  1359            break;
  1360          }
  1361
  1362          if(ja3.server.num_tls_extension < MAX_NUM_JA3)
  1363            ja3.server.tls_extension[ja3.server.num_tls_extension++] = extension_id;
  1364
  1365  #ifdef DEBUG_TLS
  1366          printf("TLS [server][extension_id: %u/0x%04X][len: %u]\n",
  1367                 extension_id, extension_id, extension_len);
  1368  #endif
  1369          checkExtensions(ndpi_struct, flow, is_dtls, extension_id, extension_len, offset + 4);
  1370
  1371          if(extension_id == 43 /* supported versions */) {
  1372            if(extension_len >= 2) {
  1373              u_int16_t tls_version = ntohs(*((u_int16_t*)&packet->payload[offset+4]));
  1374
  1375  #ifdef DEBUG_TLS
  1376              printf("TLS [server] [TLS version: 0x%04X]\n", tls_version);
  1377  #endif
  1378
  1379              flow->protos.tls_quic.ssl_version = ja3.server.tls_supported_version = tls_version;
  1380            }
