  1384            u_int16_t tot_alpn_len = ntohs(*((u_int16_t*)&packet->payload[s_offset]));
  1385            char alpn_str[256];
  1386            u_int8_t alpn_str_len = 0, i;
  1387
  1388  #ifdef DEBUG_TLS
  1389            printf("Server TLS [ALPN: block_len=%u/len=%u]\n", extension_len, tot_alpn_len);
  1390  #endif
  1391            s_offset += 2;
  1392            tot_alpn_len += s_offset;
  1393
  1394            if(tot_alpn_len > packet->payload_packet_len)
  1395              return 0;
  1396
