  1398              u_int8_t alpn_i, alpn_len = packet->payload[s_offset++];
  1399
  1400              if((s_offset + alpn_len) <= tot_alpn_len) {
  1401  #ifdef DEBUG_TLS
  1402                printf("Server TLS [ALPN: %u]\n", alpn_len);
  1403  #endif
  1404
  1405                if(((uint32_t)alpn_str_len+alpn_len+1) < (sizeof(alpn_str)-1)) {
  1406                  if(alpn_str_len > 0) {
  1407                    alpn_str[alpn_str_len] = ',';
  1408                    alpn_str_len++;
  1409                  }
  1410
  1411                  for(alpn_i=0; alpn_i<alpn_len; alpn_i++)
  1412                  {
  1413                    alpn_str[alpn_str_len+alpn_i] = packet->payload[s_offset+alpn_i];
  1414                  }
  1415
  1416                  s_offset += alpn_len, alpn_str_len += alpn_len;;
  1417                } else {
  1418                  ndpi_set_risk(ndpi_struct, flow, NDPI_TLS_UNCOMMON_ALPN);
  1419                  break;
  1420                }
  1421              } else {
  1422                ndpi_set_risk(ndpi_struct, flow, NDPI_TLS_UNCOMMON_ALPN);
  1423                break;
  1424              }
  1425            } /* while */
  1426
  1427            alpn_str[alpn_str_len] = '\0';
  1428
  1429  #ifdef DEBUG_TLS
  1430            printf("Server TLS [ALPN: %s][len: %u]\n", alpn_str, alpn_str_len);
  1431  #endif
  1432            if(ndpi_is_printable_string(alpn_str, alpn_str_len) == 0)
  1433              ndpi_set_risk(ndpi_struct, flow, NDPI_INVALID_CHARACTERS);
  1434
  1435            if(flow->protos.tls_quic.alpn == NULL)
  1436              flow->protos.tls_quic.alpn = ndpi_strdup(alpn_str);
  1437
  1438            if(flow->protos.tls_quic.alpn != NULL)
  1439              tlsCheckUncommonALPN(ndpi_struct, flow);
  1440
  1441            snprintf(ja3.server.alpn, sizeof(ja3.server.alpn), "%s", alpn_str);
  1442
  1443            /* Replace , with - as in JA3 */
  1444            for(i=0; ja3.server.alpn[i] != '\0'; i++)
  1445              if(ja3.server.alpn[i] == ',') ja3.server.alpn[i] = '-';
  1446          } else if(extension_id == 11 /* ec_point_formats groups */) {
  1447            u_int16_t s_offset = offset+4 + 1;
  1448
  1449  #ifdef DEBUG_TLS
  1450            printf("Server TLS [EllipticCurveFormat: len=%u]\n", extension_len);
  1451  #endif
  1452            if((s_offset+extension_len-1) <= total_len) {
  1453              for(i=0; i<extension_len-1 && s_offset+i<packet->payload_packet_len; i++) {
  1454                u_int8_t s_group = packet->payload[s_offset+i];
  1455
  1456  #ifdef DEBUG_TLS
  1457                printf("Server TLS [EllipticCurveFormat: %u]\n", s_group);
  1458  #endif
  1459
  1460                if(ja3.server.num_elliptic_curve_point_format < MAX_NUM_JA3)
  1461                  ja3.server.elliptic_curve_point_format[ja3.server.num_elliptic_curve_point_format++] = s_group;
  1462                else {
  1463                  invalid_ja3 = 1;
  1464  #ifdef DEBUG_TLS
  1465                  printf("Server TLS Invalid num elliptic %u\n", ja3.server.num_elliptic_curve_point_format);
  1466  #endif
  1467                }
  1468              }
  1469            } else {
  1470              invalid_ja3 = 1;
  1471  #ifdef DEBUG_TLS
  1472              printf("Server TLS Invalid len %u vs %u\n", s_offset+extension_len, total_len);
  1473  #endif
  1474            }
  1475          }
  1476
  1477          i += 4 + extension_len, offset += 4 + extension_len;
  1478        } /* for */
  1479
  1480        ja3_str_len = snprintf(ja3_str, JA3_STR_LEN, "%u,", ja3.server.tls_handshake_version);
  1481
  1482        for(i=0; (i<ja3.server.num_cipher) && (JA3_STR_LEN > ja3_str_len); i++) {
  1483          rc = snprintf(&ja3_str[ja3_str_len], JA3_STR_LEN-ja3_str_len, "%s%u", (i > 0) ? "-" : "", ja3.server.cipher[i]);
  1484
  1485          if(rc <= 0) break; else ja3_str_len += rc;
  1486        }
  1487
  1488        if(JA3_STR_LEN > ja3_str_len) {
  1489          rc = snprintf(&ja3_str[ja3_str_len], JA3_STR_LEN-ja3_str_len, ",");
  1490          if(rc > 0 && ja3_str_len + rc < JA3_STR_LEN) ja3_str_len += rc;
  2190              } /* while */
  2191
  2192              if(!invalid_ja3) {
  2193                int rc;
  2194
  2195              compute_ja3c:
  2196                ja3_str_len = snprintf(ja3_str, JA3_STR_LEN, "%u,", ja3.client.tls_handshake_version);
  2197
  2198                for(i=0; i<ja3.client.num_cipher; i++) {
  2199                  rc = snprintf(&ja3_str[ja3_str_len], JA3_STR_LEN-ja3_str_len, "%s%u",
  2200                                (i > 0) ? "-" : "", ja3.client.cipher[i]);
  2201                  if((rc > 0) && (ja3_str_len + rc < JA3_STR_LEN)) ja3_str_len += rc; else break;
  2202                }
  2203
  2204                rc = snprintf(&ja3_str[ja3_str_len], JA3_STR_LEN-ja3_str_len, ",");
  2205                if((rc > 0) && (ja3_str_len + rc < JA3_STR_LEN)) ja3_str_len += rc;
  2206
  2207                /* ********** */
  2208
  2209                for(i=0; i<ja3.client.num_tls_extension; i++) {
  2210                  rc = snprintf(&ja3_str[ja3_str_len], JA3_STR_LEN-ja3_str_len, "%s%u",
  2211                                (i > 0) ? "-" : "", ja3.client.tls_extension[i]);
  2212                  if((rc > 0) && (ja3_str_len + rc < JA3_STR_LEN)) ja3_str_len += rc; else break;
  2213                }
  2214
  2215                rc = snprintf(&ja3_str[ja3_str_len], JA3_STR_LEN-ja3_str_len, ",");
  2216                if((rc > 0) && (ja3_str_len + rc < JA3_STR_LEN)) ja3_str_len += rc;
  2217
  2218                /* ********** */
  2219
  2220                for(i=0; i<ja3.client.num_elliptic_curve; i++) {
  2221                  rc = snprintf(&ja3_str[ja3_str_len], JA3_STR_LEN-ja3_str_len, "%s%u",
  2222                                (i > 0) ? "-" : "", ja3.client.elliptic_curve[i]);
  2223                  if((rc > 0) && (ja3_str_len + rc < JA3_STR_LEN)) ja3_str_len += rc; else break;
  2224                }
  2225
  2226                rc = snprintf(&ja3_str[ja3_str_len], JA3_STR_LEN-ja3_str_len, ",");
  2227                if((rc > 0) && (ja3_str_len + rc < JA3_STR_LEN)) ja3_str_len += rc;
  2228
  2229                for(i=0; i<ja3.client.num_elliptic_curve_point_format; i++) {
  2230                  rc = snprintf(&ja3_str[ja3_str_len], JA3_STR_LEN-ja3_str_len, "%s%u",
  2231                                (i > 0) ? "-" : "", ja3.client.elliptic_curve_point_format[i]);
  2232                  if((rc > 0) && (ja3_str_len + rc < JA3_STR_LEN)) ja3_str_len += rc; else break;
  2233                }
  2234
  2235                if(ndpi_struct->enable_ja3_plus) {
  2236                  rc = snprintf(&ja3_str[ja3_str_len], JA3_STR_LEN-ja3_str_len,
  2237                                ",%s,%s,%s", ja3.client.signature_algorithms, ja3.client.supported_versions, ja3.client.alpn);
  2238                  if((rc > 0) && (ja3_str_len + rc < JA3_STR_LEN)) ja3_str_len += rc;
  2239                }
  2240
  2241  #ifdef DEBUG_JA3C
  2242                printf("[JA3+] Client: %s \n", ja3_str);
  2243  #endif
  2244
  2245                ndpi_MD5Init(&ctx);
  2246                ndpi_MD5Update(&ctx, (const unsigned char *)ja3_str, strlen(ja3_str));
  2247                ndpi_MD5Final(md5_hash, &ctx);
  2248
  2249                for(i=0, j=0; i<16; i++) {
  2250                  rc = snprintf(&flow->protos.tls_quic.ja3_client[j],
  2251                                sizeof(flow->protos.tls_quic.ja3_client)-j, "%02x",
  2252                                md5_hash[i]);
  2253                  if(rc > 0) j += rc; else break;
  2254                }
  2255
  2256  #ifdef DEBUG_JA3C
  2257                printf("[JA3] Client: %s \n", flow->protos.tls_quic.ja3_client);
