  2280              }
  2281
  2282              /* Add check for missing SNI */
  2283              if(flow->host_server_name[0] == '\0'
  2284                 && (flow->protos.tls_quic.ssl_version >= 0x0302) /* TLSv1.1 */
  2285                 && (flow->protos.tls_quic.encrypted_sni.esni == NULL) /* No ESNI */
  2286                 ) {
  2287                /* This is a bit suspicious */
  2288                ndpi_set_risk(ndpi_struct, flow, NDPI_TLS_MISSING_SNI);
  2289              }
  2290
  2291              return(2 /* Client Certificate */);
  2292            } else {
  2293  #ifdef DEBUG_TLS
  2294              printf("[TLS] Client: too short [%u vs %u]\n",
  2295                     (extensions_len+offset), total_len);
  2296  #endif
  2297            }
  2298          } else if(offset == total_len) {
  2299            /* TLS does not have extensions etc */
  2300            goto compute_ja3c;
  2301          }
  2302        } else {
  2303  #ifdef DEBUG_TLS
  2304          printf("[JA3] Client: invalid length detected\n");
  2305  #endif
  2306        }
  2307      }
  2308    }
  2309
  2310    return(0); /* Not found */
  2311  }
